import org.zhbot.golem_crafting.GolemCraftingPlugin;
import org.zhbot.golem_crafting.enums.SunstoneMode;
import org.zhbot.golem_crafting.utils.GraphicsUtils;
import org.zhbot.golem_crafting.utils.TextUtils;

import javax.inject.Inject;
import java.awt.*;
import java.util.List;
import java.util.ArrayList;

public class SunstoneOverlay extends Overlay {
    private static final String MINING_ROCK_MESSAGE = "You swing your pick at the rock.";
    private static final String MINING_MONOLITH_MESSAGE = "You swing your pick at the monolith.";
    private static final String MINED_SUNSTONE_MESSAGE = "You manage to mine some sunstone.";
    private static final int MOMENTUM_TICKS = 5;

    private final Client client;
    private final GolemCraftingPlugin plugin;
    private final GolemCraftingConfig config;
    private final GraphicsUtils graphicsUtils;
    private final TextUtils textUtils;

    private boolean miningSunstoneRock = false;
    private int lastSunstoneMinedTick = -MOMENTUM_TICKS;

    private GameObject monolith;
    private final List<GameObject> upperRocks = new ArrayList<>();
    private final List<GameObject> lowerRocks = new ArrayList<>();

    @Inject
    public SunstoneOverlay(Client client, GolemCraftingPlugin plugin, GolemCraftingConfig config, GraphicsUtils graphicsUtils, TextUtils textUtils)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        this.graphicsUtils = graphicsUtils;
        this.textUtils = textUtils;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    public void startup()
    {
        var worldView = client.getTopLevelWorldView();
        if (worldView == null)
            return;

        var scene = worldView.getScene();
        if (scene == null)
            return;

        var tiles = scene.getTiles();
        if (tiles == null || tiles.length == 0)
            return;

        var zTiles = tiles[worldView.getPlane()];

        for (var xTiles : zTiles) {
            for (var tile : xTiles) {
                if (tile == null)
                    continue;

                var gameObjects = tile.getGameObjects();
                if (gameObjects == null)
                    continue;

                for (var gameObject : gameObjects)
                {
                    if (gameObject == null)
                        continue;

                    switch (gameObject.getId())
                    {
                        case ObjectID.WYRMSCRAIG_SUNSTONE01:
                            monolith = gameObject;
                            break;
                        case ObjectID.SUNSTONEROCK1:
                        case ObjectID.SUNSTONEROCK2:
                            upperRocks.add(gameObject);
                            break;
                    }
                }
            }
        }
    }

    public void shutdown()
    {
        monolith = null;
        upperRocks.clear();
        lowerRocks.clear();
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        var sunstoneMode = config.overlaySunstoneMode();
        if (sunstoneMode == SunstoneMode.NONE)
            return null;

        if (plugin.outsideGolemArea())
            return null;

        if (plugin.hasGolemMaterials())
            return null;

        var hasMomentum = config.overlaySunstoneMomentum() && hasMomentum();

        switch (sunstoneMode)
        {
            case MONOLITH:
                if (monolith == null)
                    break;

                graphicsUtils.renderObject(graphics, monolith, config.overlaySunstoneRenderStyle(), config.overlaySunstoneColour());
                break;
            case ROCKS:
                for (var rock : upperRocks)
                    graphicsUtils.renderObject(graphics, rock, config.overlaySunstoneRenderStyle(), hasMomentum ? config.overlaySunstoneMomentumColour() : config.overlaySunstoneColour());

                break;
            case ROCKS_LOWER:
                for (var rock : lowerRocks)
                    graphicsUtils.renderObject(graphics, rock, config.overlaySunstoneRenderStyle(), hasMomentum ? config.overlaySunstoneMomentumColour() : config.overlaySunstoneColour());

                break;
        }

        return null;
    }

    @Subscribe
    public void onChatMessage(ChatMessage event) {
        if (event.getType() != ChatMessageType.SPAM)
            return;

        var message = textUtils.Clean(event.getMessage());

        if (message.contains(MINING_MONOLITH_MESSAGE)) {
            miningSunstoneRock = false;
            return;
        }

        if (message.contains(MINING_ROCK_MESSAGE)) {
            miningSunstoneRock = true;
            return;
        }

        if (miningSunstoneRock && message.contains(MINED_SUNSTONE_MESSAGE)) {
            lastSunstoneMinedTick = client.getTickCount();
            return;
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        switch (event.getGameState())
        {
            case LOADING:
                monolith = null;
                upperRocks.clear();
                lowerRocks.clear();

                break;
            case LOGGED_IN:
                lastSunstoneMinedTick = -MOMENTUM_TICKS;

                break;
        }
    }

    @Subscribe
    public void onGameObjectSpawned(GameObjectSpawned event)
    {
        var object = event.getGameObject();

        switch (object.getId())
        {
            case ObjectID.WYRMSCRAIG_SUNSTONE01:
                monolith = object;

                break;
            case ObjectID.SUNSTONEROCK1:
            case ObjectID.SUNSTONEROCK2:
                if (object.getWorldLocation().getX() < 2605)
                    upperRocks.add(object);
                else
                    lowerRocks.add(object);

                break;
        }
    }

    @Subscribe
    public void onGameObjectDespawned(GameObjectDespawned event)
    {
        var object = event.getGameObject();

        switch (object.getId())
        {
            case ObjectID.WYRMSCRAIG_SUNSTONE01:
                if (object == monolith)
                    monolith = null;

                break;
            case ObjectID.SUNSTONEROCK1:
            case ObjectID.SUNSTONEROCK2:
                upperRocks.remove(object);
                lowerRocks.remove(object);

                break;
        }
    }

    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded event)
    {
        if (!config.sunstoneDeprioritiseOther())
            return;

        var sunstoneMode = config.overlaySunstoneMode();
        if (sunstoneMode == SunstoneMode.NONE)
            return;

        if (plugin.outsideGolemArea())
            return;

        var entry = event.getMenuEntry();
        if (entry.getType() != MenuAction.GAME_OBJECT_FIRST_OPTION)
            return;

        var option = textUtils.Clean(event.getOption());
        if (!option.equals("Mine"))
            return;

        var target = textUtils.Clean(event.getTarget());
        switch (target)
        {
            case "Sunstone monolith":
                if (sunstoneMode == SunstoneMode.MONOLITH)
                    return;

                break;
            case "Sunstone rocks":
                var sceneX = entry.getParam0();
                var sceneY = entry.getParam1();

                var worldView = client.getTopLevelWorldView();
                var worldPoint = WorldPoint.fromScene(worldView.getScene(), sceneX, sceneY, worldView.getPlane());

                if (worldPoint.getX() < 2605)
                {
                    if (sunstoneMode == SunstoneMode.ROCKS)
                        return;
                }
                else
                {
                    if (sunstoneMode == SunstoneMode.ROCKS_LOWER)
                        return;
                }

                break;
            default:
                return;
        }

        event.getMenuEntry().setDeprioritized(true);
    }

    private boolean hasMomentum()
    {
        var ticksSinceMined = client.getTickCount() - lastSunstoneMinedTick;
        return ticksSinceMined < MOMENTUM_TICKS;
    }

    public int getMomentumTicks()
    {
        var momentumTicks = lastSunstoneMinedTick + MOMENTUM_TICKS - client.getTickCount();
        return Math.max(momentumTicks, 0);
    }
}

package org.zhbot.golem_crafting.overlays;

import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import org.zhbot.golem_crafting.GolemCraftingConfig;
import org.zhbot.golem_crafting.GolemCraftingPlugin;
import org.zhbot.golem_crafting.utils.TextUtils;

import javax.inject.Inject;
import java.awt.*;
import java.util.Locale;

public class GolemCraftingInfobox extends OverlayPanel {
    private final Client client;
    private final GolemCraftingPlugin plugin;
    private final GolemCraftingConfig config;
    private final TextUtils textUtils;

    private int sapphireCount = 0;
    private int emeraldCount = 0;
    private int rubyCount = 0;
    private int diamondCount = 0;
    private int jewellersChiselCount = 0;

    @Inject
    private GolemCraftingInfobox(Client client, GolemCraftingPlugin plugin, GolemCraftingConfig config, TextUtils textUtils)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        this.textUtils = textUtils;

        setPosition(OverlayPosition.TOP_LEFT);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (plugin.outsideGolemArea())
            return super.render(graphics);

        panelComponent.getChildren().add(TitleComponent.builder()
                .text("Golem Crafting")
                .color(plugin.isCrafting() ? Color.GREEN : Color.RED)
                .build());

        if (config.showInfoboxTotal())
        {
            panelComponent.getChildren().add(LineComponent.builder()
                    .left("Total Golems:")
                    .right(String.valueOf(client.getVarbitValue(VarbitID.GOLEM_CRAFTING_COUNT)))
                    .build());
        }

        if (config.showInfoboxState())
        {
            for (var golem : plugin.getGolems())
            {
                panelComponent.getChildren().add(LineComponent.builder()
                        .left(golem.getName() + ":")
                        .right(golem.getProgress() + "/6")
                        .build());
            }
        }

        if (config.showInfoboxFurPouch())
        {
            var furPouch = plugin.getFurPouch();
            var furPouchCount = furPouch.getCount();

            Color color;
            if (furPouchCount == 0)
                color = config.infoboxFurPouchEmptyTextColour();
            else if (furPouchCount == -1)
                color = config.infoboxFurPouchUnknownTextColour();
            else if (furPouchCount <= config.furPouchLowThreshold())
                color = config.infoboxFurPouchLowTextColour();
            else
                color = Color.WHITE;
            panelComponent.getChildren().add(LineComponent.builder()
                    .left("Fur Pouch:")
                    .right(furPouch.hasFurPouch() ? furPouchCount + "/" + furPouch.getCapacity() : "N/A")
                    .rightColor(color)
                    .build());
        }

        if (config.showInfoboxFur())
        {
            panelComponent.getChildren().add(LineComponent.builder()
                    .left("Fur:")
                    .right(String.valueOf(plugin.getFurCount()))
                    .build());
        }

        if (config.showInfoboxSunStone())
        {
            panelComponent.getChildren().add(LineComponent.builder()
                    .left("Sunstone Core:")
                    .right(String.valueOf(plugin.getSunstoneCoreCount()))
                    .build());
            panelComponent.getChildren().add(LineComponent.builder()
                    .left("Sunstone:")
                    .right(String.valueOf(plugin.getSunstoneCount()))
                    .build());
        }

        if (config.showInfoboxSunStoneMomentum())
        {
            var ticks = plugin.getSunstoneOverlay().getMomentumTicks();
            panelComponent.getChildren().add(LineComponent.builder()
                    .left("Momentum:")
                    .right(String.valueOf(ticks))
                    .rightColor(ticks > 0 ? Color.GREEN : Color.RED)
                    .build());
        }

        if (config.showInfoboxLoot())
        {
            panelComponent.getChildren().add(TitleComponent.builder()
                    .text("Session Loot")
                    .color(Color.GREEN)
                    .build());

            panelComponent.getChildren().add(LineComponent.builder()
                    .left("Uncut Sapphire:")
                    .right(String.valueOf(sapphireCount))
                    .build());

            panelComponent.getChildren().add(LineComponent.builder()
                    .left("Uncut Emerald:")
                    .right(String.valueOf(emeraldCount))
                    .build());

            panelComponent.getChildren().add(LineComponent.builder()
                    .left("Uncut Ruby:")
                    .right(String.valueOf(rubyCount))
                    .build());

            panelComponent.getChildren().add(LineComponent.builder()
                    .left("Uncut Diamond:")
                    .right(String.valueOf(diamondCount))
                    .build());

            panelComponent.getChildren().add(LineComponent.builder()
                    .left("Jeweller's Chisel:")
                    .right(String.valueOf(jewellersChiselCount))
                    .build());
        }

        return super.render(graphics);
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        if (event.getType() != ChatMessageType.GAMEMESSAGE)
            return;

        var message = textUtils.Clean(event.getMessage());

        var lootMatcher = GolemCraftingPlugin.LOOT_MESSAGE.matcher(message);
        if (!lootMatcher.matches())
            return;

        var lootAmount = Integer.parseInt(lootMatcher.group(2));
        var loot = lootMatcher.group(3).toLowerCase(Locale.ROOT);

        switch (loot)
        {
            case "uncut sapphire":
                sapphireCount += lootAmount;
                break;
            case "uncut emerald":
                emeraldCount += lootAmount;
                break;
            case "uncut ruby":
                rubyCount += lootAmount;
                break;
            case "uncut diamond":
                diamondCount += lootAmount;
                break;
            case "jeweller's chisel":
                jewellersChiselCount += lootAmount;
                break;
        }
    }
}

package org.zhbot.golem_crafting.overlays;

import net.runelite.api.Client;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import org.zhbot.golem_crafting.GolemCraftingConfig;
import org.zhbot.golem_crafting.GolemCraftingPlugin;

import javax.inject.Inject;
import java.awt.*;

public class ResourceWarningInfobox extends OverlayPanel {
    private final Client client;
    private final GolemCraftingPlugin plugin;
    private final GolemCraftingConfig config;

    @Inject
    private ResourceWarningInfobox(Client client, GolemCraftingPlugin plugin, GolemCraftingConfig config)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;

        setPosition(OverlayPosition.ABOVE_CHATBOX_RIGHT);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (plugin.outsideGolemArea())
            return null;

        var inventory = client.getItemContainer(InventoryID.INV);
        if (inventory == null)
            return null;

        panelComponent.getChildren().clear();

        var empty = false;
        var low = false;

        if (config.resourceInfoboxWarnChisel() && !plugin.isHasChisel())
        {
            panelComponent.getChildren().add(LineComponent.builder()
                    .left("Chisel")
                    .right("Missing")
                    .build());
            empty = true;
        }

        if (config.resourceInfoboxWarnHammer() && !(plugin.isHasHammer() || plugin.isHasHammerEquipped()))
        {
            panelComponent.getChildren().add(LineComponent.builder()
                    .left("Hammer")
                    .right("Missing")
                    .build());
            empty = true;
        }

        if (plugin.getFurPouch().hasFurPouch() && plugin.getFurPouch().getCount() == -1)
        {
            panelComponent.getChildren().add(LineComponent.builder()
                    .left("Fur Pouch")
                    .right("Unknown")
                    .build());
            empty = true;
        }
        else if (config.resourceInfoboxWarnFur())
        {
            var furCount = plugin.getTotalFurCount();

            if (furCount == 0)
            {
                panelComponent.getChildren().add(LineComponent.builder()
                        .left("Fur")
                        .right("Empty")
                        .build());
                empty = true;
            }
            else if (furCount <= config.resourceInfoboxFurThreshold())
            {
                panelComponent.getChildren().add(LineComponent.builder()
                        .left("Fur")
                        .right("Low")
                        .build());
                low = true;
            }
        }

        if (config.resourceInfoboxWarnSunstone())
        {
            var sunstoneCount = inventory.count(ItemID.SUNSTONE);

            if (sunstoneCount == 0)
            {
                panelComponent.getChildren().add(LineComponent.builder()
                        .left("Sunstone")
                        .right("Empty")
                        .build());
                empty = true;
            }
            else if (sunstoneCount <= config.resourceInfoboxSunstoneThreshold())
            {
                panelComponent.getChildren().add(LineComponent.builder()
                        .left("Sunstone")
                        .right("Low")
                        .build());
                low = true;
            }
        }

        if (config.resourceInfoboxWarnSunstoneCore())
        {
            var sunstoneCoreCount = inventory.count(ItemID.SUNSTONE_CORE);

            if (sunstoneCoreCount == 0)
            {
                panelComponent.getChildren().add(LineComponent.builder()
                        .left("Cores")
                        .right("Empty")
                        .build());
                empty = true;
            }
            else if (sunstoneCoreCount <= config.resourceInfoboxCoreThreshold())
            {
                panelComponent.getChildren().add(LineComponent.builder()
                        .left("Cores")
                        .right("Low")
                        .build());
                low = true;
            }
        }

        if (!empty && !low)
            return null;

        if (empty)
            panelComponent.setBackgroundColor((!config.resourceInfoboxFlash() || client.getGameCycle() % 40 < 20) ? config.resourceInfoboxEmptyColour1() : config.resourceInfoboxEmptyColour2());
        else
            panelComponent.setBackgroundColor(config.resourceInfoboxLowColour());

        return panelComponent.render(graphics);
    }
}

package org.zhbot.golem_crafting.overlays;

import net.runelite.api.Client;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import org.zhbot.golem_crafting.GolemCraftingConfig;
import org.zhbot.golem_crafting.GolemCraftingPlugin;
import org.zhbot.golem_crafting.enums.CardinalDirection;
import org.zhbot.golem_crafting.enums.TileMode;
import org.zhbot.golem_crafting.golems.Golem;
import org.zhbot.golem_crafting.utils.GraphicsUtils;

import java.awt.*;

public class GolemOverlay extends Overlay {
    private final Client client;
    private final GolemCraftingPlugin plugin;
    private final GolemCraftingConfig config;
    private final GraphicsUtils graphicsUtils;
    private final Golem golem;

    public GolemOverlay(Client client, GolemCraftingPlugin plugin, GolemCraftingConfig config, GraphicsUtils graphicsUtils, Golem golem)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        this.graphicsUtils = graphicsUtils;
        this.golem = golem;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        var tileMode = config.showTilesMode();
        var progress = golem.getProgress();
        if (progress == 0)
        {
            if (!plugin.hasGolemMaterials())
                return null;

            var activeGolem = plugin.getActiveGolem();
            if (activeGolem != null)
            {
                if (activeGolem.getProgress() == 5 && tileMode.isShowOptimal())
                    graphicsUtils.renderTile(graphics, golem.getStartTile(), config.overlayTileNextOptimalColour());

                return null;
            }

            var station = golem.getStationGameObject();
            if (station == null)
                return null;

            var ticksSinceProgress = client.getTickCount() - golem.getLastProgressTick();
            if (ticksSinceProgress < Golem.RESPAWN_DELAY)
            {
                graphicsUtils.renderPie(graphics, station.getCanvasLocation(0), (double)ticksSinceProgress / Golem.RESPAWN_DELAY, Color.ORANGE);
            }
            else
            {
                if (config.showOverlayPlinth())
                    graphicsUtils.renderObject(graphics, station, config.overlayPlinthRenderStyle(), config.overlayPlinthValidColour());

                if (tileMode.isShowOptimal())
                    graphicsUtils.renderTile(graphics, golem.getStartTile(), config.overlayTileOptimalColour());
            }

            return null;
        }

        var player = client.getLocalPlayer();
        if (player == null)
            return null;
        var playerLocation = player.getWorldLocation();
        var onValidTile = false;

        var currentOptimalSide = golem.getCurrentOptimalSide();
        var nextOptimalSide = golem.getNextOptimalSide();
        var currentSide = CardinalDirection.NONE;
        var isFinalStep = progress == 5;
        if (isFinalStep)
        {
            onValidTile = playerLocation.distanceTo(golem.getFinalTile()) == 0;

            if (tileMode.isShowIncomplete() || tileMode.isShowOptimal())
                graphicsUtils.renderTile(graphics, golem.getFinalTile(), config.overlayTileColour());
        }
        else
        {
            if (!golem.isNorthDone())
            {
                if (playerLocation.distanceTo(golem.getNorthTile()) == 0)
                {
                    onValidTile = true;
                    currentSide = CardinalDirection.NORTH;
                }

                if (tileMode.isShowOptimal() && nextOptimalSide == CardinalDirection.NORTH)
                    graphicsUtils.renderTile(graphics, golem.getNorthTile(), config.overlayTileNextOptimalColour());
                else if (tileMode.isShowOptimal() && currentOptimalSide == CardinalDirection.NORTH)
                    graphicsUtils.renderTile(graphics, golem.getNorthTile(), config.overlayTileOptimalColour());
                else if (tileMode.isShowIncomplete())
                    graphicsUtils.renderTile(graphics, golem.getNorthTile(), config.overlayTileColour());

                if (config.showProgressMode().isShowTiles())
                    graphicsUtils.renderPie(graphics, golem.getNorthTile(), golem.getNorthProgress(), config.overlayProgressColour());
            }
            else if (tileMode.isShowComplete())
            {
                graphicsUtils.renderTile(graphics, golem.getNorthTile(), config.overlayTileCompleteColour());
            }

            if (!golem.isEastDone())
            {
                if (playerLocation.distanceTo(golem.getEastTile()) == 0)
                {
                    onValidTile = true;
                    currentSide = CardinalDirection.EAST;
                }

                if (tileMode.isShowOptimal() && nextOptimalSide == CardinalDirection.EAST)
                    graphicsUtils.renderTile(graphics, golem.getEastTile(), config.overlayTileNextOptimalColour());
                else if (tileMode.isShowOptimal() && currentOptimalSide == CardinalDirection.EAST)
                    graphicsUtils.renderTile(graphics, golem.getEastTile(), config.overlayTileOptimalColour());
                else if (tileMode.isShowIncomplete())
                    graphicsUtils.renderTile(graphics, golem.getEastTile(), config.overlayTileColour());

                if (config.showProgressMode().isShowTiles())
                    graphicsUtils.renderPie(graphics, golem.getEastTile(), golem.getEastProgress(), config.overlayProgressColour());
            }
            else if (tileMode.isShowComplete())
            {
                graphicsUtils.renderTile(graphics, golem.getEastTile(), config.overlayTileCompleteColour());
            }

            if (!golem.isSouthDone())
            {
                if (playerLocation.distanceTo(golem.getSouthTile()) == 0)
                {
                    onValidTile = true;
                    currentSide = CardinalDirection.SOUTH;
                }

                if (tileMode.isShowOptimal() && nextOptimalSide == CardinalDirection.SOUTH)
                    graphicsUtils.renderTile(graphics, golem.getSouthTile(), config.overlayTileNextOptimalColour());
                else if (tileMode.isShowOptimal() && currentOptimalSide == CardinalDirection.SOUTH)
                    graphicsUtils.renderTile(graphics, golem.getSouthTile(), config.overlayTileOptimalColour());
                else if (tileMode.isShowIncomplete())
                    graphicsUtils.renderTile(graphics, golem.getSouthTile(), config.overlayTileColour());

                if (config.showProgressMode().isShowTiles())
                    graphicsUtils.renderPie(graphics, golem.getSouthTile(), golem.getSouthProgress(), config.overlayProgressColour());
            }
            else if (tileMode.isShowComplete())
            {
                graphicsUtils.renderTile(graphics, golem.getSouthTile(), config.overlayTileCompleteColour());
            }

            if (!golem.isWestDone())
            {
                if (playerLocation.distanceTo(golem.getWestTile()) == 0)
                {
                    onValidTile = true;
                    currentSide = CardinalDirection.WEST;
                }

                if (tileMode.isShowOptimal() && nextOptimalSide == CardinalDirection.WEST)
                    graphicsUtils.renderTile(graphics, golem.getWestTile(), config.overlayTileNextOptimalColour());
                else if (tileMode.isShowOptimal() && currentOptimalSide == CardinalDirection.WEST)
                    graphicsUtils.renderTile(graphics, golem.getWestTile(), config.overlayTileOptimalColour());
                else if (tileMode.isShowIncomplete())
                    graphicsUtils.renderTile(graphics, golem.getWestTile(), config.overlayTileColour());

                if (config.showProgressMode().isShowTiles())
                    graphicsUtils.renderPie(graphics, golem.getWestTile(), golem.getWestProgress(), config.overlayProgressColour());
            }
            else if (tileMode.isShowComplete())
            {
                graphicsUtils.renderTile(graphics, golem.getWestTile(), config.overlayTileCompleteColour());
            }
        }

        var station = golem.getStationGameObject();
        if (station == null)
            return null;

        if (config.showOverlayPlinth())
        {
            Color color;
            if (!onValidTile)
                color = isFinalStep ? config.overlayPlinthInvalidCoreColour() : config.overlayPlinthInvalidColour();
            else if (config.showOverlayPlinthEfficiency() && progress > 0 && progress < 5 && plugin.isCrafting() && client.getVarbitValue(VarbitID.BUSY) == 0 && plugin.getLastBusyTick() >= golem.getLastShapeClickTick())
                color = config.overlayPlinthEfficiencyColour();
            else
                color = (isFinalStep ? config.overlayPlinthValidCoreColour() : config.overlayPlinthValidColour());
            graphicsUtils.renderObject(graphics, station, config.overlayPlinthRenderStyle(), color);
        }

        if (isFinalStep)
        {
            if (config.showOverlayPlinthCore())
                graphicsUtils.renderItem(graphics, station, ItemID.SUNSTONE_CORE, config.overlayZOffset());

            if (config.showOverlayGolemOnInsertCore())
                graphicsUtils.renderTile(graphics, golem.getGolemTile(), config.overlayTileGolemOnInsertColour());
        }
        else if (currentSide != CardinalDirection.NONE && config.showProgressMode().isShowPlinth())
        {
            var currentProgress = 0d;
            switch (currentSide)
            {
                case NORTH:
                    currentProgress = golem.getNorthProgress();
                    break;
                case EAST:
                    currentProgress = golem.getEastProgress();
                    break;
                case SOUTH:
                    currentProgress = golem.getSouthProgress();
                    break;
                case WEST:
                    currentProgress = golem.getWestProgress();
                    break;
            }

            graphicsUtils.renderPie(graphics, station, currentProgress, config.overlayProgressColour(), config.overlayZOffset());
        }


        return null;
    }
}

